package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type AmtRec struct {
	ArAcct string
	ArAmt  decimal.Decimal
}

var WsEofFlag string = "N"
var WsBigTotal decimal.Decimal = decimal.NewFromInt(0)
var WsWrapTotal decimal.Decimal = decimal.NewFromInt(0)
var WsSafeTotal decimal.Decimal = decimal.NewFromInt(0)
var WsOverflows int64 = 0
var WsCount int64 = 0
var WsHalf decimal.Decimal = decimal.NewFromInt(0)
var WsAmtEd string
var WsWrapEd string
var WsSafeEd string
var WsHalfEd string

var amtFile *os.File
var amtReader *bufio.Reader
var currentRec AmtRec

func storeDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// Truncate toward zero to scale (COBOL without ROUNDED)
	v = v.Truncate(scale)
	// Keep only low-order digits that fit: modulo 10^intDigits
	// For positive values: v mod 10^intDigits, preserving scale
	// Use decimal modulo via integer representation
	// Compute modulus = 10^intDigits
	modInt := decimal.NewFromInt(1)
	ten := decimal.NewFromInt(10)
	for i := 0; i < intDigits; i++ {
		modInt = modInt.Mul(ten)
	}
	// For negative, COBOL would keep low order digits but keep sign; inputs are positive.
	if v.IsNegative() {
		// keep sign
		abs := v.Abs()
		// abs modulo modInt
		// split integer and fractional
		// Use: remainder = abs - floor(abs / modInt)*modInt
		q := abs.Div(modInt).Truncate(0) // integer quotient
		rem := abs.Sub(q.Mul(modInt))
		return rem.Neg()
	}
	q := v.Div(modInt).Truncate(0)
	rem := v.Sub(q.Mul(modInt))
	// ensure scale
	rem = rem.Truncate(scale)
	return rem
}

func maxValue(intDigits int, scale int32) decimal.Decimal {
	// 999... with scale digits all 9
	// = 10^intDigits - 10^-scale
	ten := decimal.NewFromInt(10)
	powInt := decimal.NewFromInt(1)
	for i := 0; i < intDigits; i++ {
		powInt = powInt.Mul(ten)
	}
	// smallest unit
	unit := decimal.New(1, -scale)
	max := powInt.Sub(unit)
	return max
}

func formatEdited(v decimal.Decimal, pic string) string {
	// pic like "ZZ,ZZ9.99" or "ZZ,ZZ9.9"
	// Determine width = len(pic), decimal places = after '.'
	dot := strings.Index(pic, ".")
	var intPic, fracPic string
	var fracDigits int
	if dot >= 0 {
		intPic = pic[:dot]
		fracPic = pic[dot+1:]
		fracDigits = len(fracPic)
	} else {
		intPic = pic
		fracDigits = 0
	}
	width := len(pic)

	// High-order truncation: keep only low order integer digits that fit.
	// Count digit positions in intPic (Z,9,',')? Commas occupy width but not digit capacity.
	// Digit capacity = count of Z and 9 in intPic.
	digitCap := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			digitCap++
		}
	}
	// Truncate value to fracDigits (should already), and drop high digits
	v = v.Truncate(int32(fracDigits))
	isNeg := v.IsNegative()
	if isNeg {
		v = v.Abs()
	}
	// Extract integer and fractional parts
	pow10 := decimal.New(1, int32(fracDigits))
	// work in scaled integer
	scaled := v.Mul(pow10).Truncate(0) // integer
	// integer part = scaled / pow10
	intPart := scaled.Div(pow10).Truncate(0)
	fracPart := scaled.Sub(intPart.Mul(pow10)).Abs()
	// high-order truncation on integer part
	if digitCap > 0 {
		mod := decimal.NewFromInt(1)
		ten := decimal.NewFromInt(10)
		for i := 0; i < digitCap; i++ {
			mod = mod.Mul(ten)
		}
		q := intPart.Div(mod).Truncate(0)
		intPart = intPart.Sub(q.Mul(mod))
	}
	// Build integer string with digitCap digits, zero padded
	intStr := intPart.StringFixed(0) // no decimal
	// pad to digitCap
	if len(intStr) < digitCap {
		intStr = strings.Repeat("0", digitCap-len(intStr)) + intStr
	} else if len(intStr) > digitCap {
		intStr = intStr[len(intStr)-digitCap:]
	}
	// Now map to intPic from right to left
	// intPic chars include ',' and 'Z'/'9'
	// We need to place digits into Z/9 positions
	outInt := make([]byte, len(intPic))
	digitIdx := len(intStr) - 1
	for i := len(intPic) - 1; i >= 0; i-- {
		c := intPic[i]
		if c == 'Z' || c == '9' {
			outInt[i] = intStr[digitIdx]
			digitIdx--
		} else {
			outInt[i] = byte(c) // ','
		}
	}
	// Apply Z suppression: leading zeros become spaces, commas in suppressed zone become spaces
	// Find first non-zero digit position in terms of digit positions
	// Suppression applies to Z positions only; a 9 always prints (even if zero)
	// But Z's that are leading zeros -> space; commas between become spaces if all digits to left are suppressed.
	// Implementation: iterate outInt left to right, track if we have seen a non-zero digit (or a 9 position forces stop)
	// Determine the index of last Z that should be suppressed.
	// Approach: find position of first non-zero digit among the digit characters.
	firstNonZeroPos := -1 // index in outInt
	for i, ch := range outInt {
		if intPic[i] == 'Z' || intPic[i] == '9' {
			if ch != '0' {
				firstNonZeroPos = i
				break
			}
			// if it's '9' and zero, it is not considered non-zero but it stops suppression?
			// In COBOL, 9 always prints, so zeros in 9 positions are printed. So suppression stops before a '9' position.
			if intPic[i] == '9' {
				// 9 position: suppression ends; if all previous were zero, we still don't suppress this
				// Mark as boundary if it's the last 9 before end: the zeros up to before it may be suppressed, but this 9 stays
				// So we can consider that suppression should not include this and after
				// If we haven't found non-zero, the first '9' is where suppression stops.
				firstNonZeroPos = i
				// But if the digit is '0', we still want to keep it (print 0). So treat as non-zero for suppression boundary.
				break
			}
		}
	}
	// If all digits zero, then firstNonZeroPos will be the first '9' (the mandatory digit)
	// If no '9' (not case), then all suppressed -> all spaces except maybe?
	if firstNonZeroPos == -1 {
		// all Z zeros and no 9? then everything suppressed -> spaces
		for i := range outInt {
			if intPic[i] == 'Z' {
				outInt[i] = ' '
			} else if outInt[i] == ',' {
				outInt[i] = ' '
			}
		}
	} else {
		for i := 0; i < firstNonZeroPos; i++ {
			if outInt[i] == '0' {
				outInt[i] = ' '
			}
			if outInt[i] == ',' {
				// if everything to left is spaces/zero-suppressed, comma becomes space
				// Since we iterate left to right, any comma before firstNonZeroPos should be space
				outInt[i] = ' '
			}
		}
		// Z positions that were zero but before firstNonZeroPos already handled (turned to space)
		// Any '0' that was in Z position before firstNonZeroPos should be space (done)
	}

	intFormatted := string(outInt)

	if fracDigits > 0 {
		fracStr := fracPart.StringFixed(0)
		if len(fracStr) < fracDigits {
			fracStr = strings.Repeat("0", fracDigits-len(fracStr)) + fracStr
		}
		result := intFormatted + "." + fracStr
		// Ensure width matches (should)
		if len(result) < width {
			result = strings.Repeat(" ", width-len(result)) + result
		}
		if isNeg {
			// not needed
		}
		return result
	}
	return intFormatted
}

func formatPIC99(v int64) string {
	s := fmt.Sprintf("%02d", v%100)
	if len(s) > 2 {
		s = s[len(s)-2:]
	}
	return s
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func MainPara() {
	var err error
	amtFile, err = os.Open("input.dat")
	if err != nil {
		// if file not exists, treat as empty
		WsEofFlag = "Y"
	} else {
		amtReader = bufio.NewReader(amtFile)
	}
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if amtFile != nil {
		amtFile.Close()
	}
	SummaryPara()
}

func ReadPara() {
	if amtReader == nil {
		WsEofFlag = "Y"
		return
	}
	line, err := amtReader.ReadString('\n')
	if err != nil {
		// EOF: check if we got data
		if len(line) == 0 {
			WsEofFlag = "Y"
			return
		}
	}
	// strip newline
	line = strings.TrimRight(line, "\r\n")
	// pad to 11
	if len(line) < 11 {
		line = line + strings.Repeat(" ", 11-len(line))
	}
	if len(line) > 11 {
		line = line[:11]
	}
	arAcct := line[0:4]
	arAmtRaw := line[4:11] // 7 digits
	// parse digits only
	digits := ""
	for _, ch := range arAmtRaw {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		} else {
			digits += "0"
		}
	}
	// decimal with scale 2
	// arAmtRaw is PIC 9(5)V99 => 7 digits integer representing value*100
	var amt decimal.Decimal
	if digits == "" {
		amt = decimal.NewFromInt(0)
	} else {
		// parse as integer
		i, _ := decimal.NewFromString(digits)
		amt = decimal.New(i.IntPart(), -2)
	}
	currentRec = AmtRec{ArAcct: arAcct, ArAmt: amt}
}

func ProcessPara() {
	// ADD AR-AMT TO WS-BIG-TOTAL
	WsBigTotal = WsBigTotal.Add(currentRec.ArAmt)
	WsBigTotal = storeDecimal(WsBigTotal, 7, 2)

	// MOVE WS-BIG-TOTAL TO WS-WRAP-TOTAL (wrap)
	WsWrapTotal = storeDecimal(WsBigTotal, 5, 2)

	// ADD AR-AMT TO WS-SAFE-TOTAL ON SIZE ERROR
	tentative := WsSafeTotal.Add(currentRec.ArAmt)
	tentative = tentative.Truncate(2)
	maxSafe := maxValue(5, 2)
	overflow := tentative.GreaterThan(maxSafe) || tentative.IsNegative() // negative overflow not expected
	if overflow {
		OverflowPara()
		// BUG: the following statements are considered part of ON SIZE ERROR branch
		// So they execute only on overflow
		WsCount = (WsCount + 1) % 100
		// COMPUTE WS-HALF = AR-AMT / 2  (truncated)
		halfRaw := currentRec.ArAmt.Div(decimal.NewFromInt(2))
		// Actually need Shift? Use Div then Truncate
		WsHalf = storeDecimal(halfRaw.Truncate(1), 5, 1)
		WsAmtEd = formatEdited(currentRec.ArAmt, "ZZ,ZZ9.99")
		WsWrapEd = formatEdited(WsWrapTotal, "ZZ,ZZ9.99")
		WsSafeEd = formatEdited(WsSafeTotal, "ZZ,ZZ9.99")
		WsHalfEd = formatEdited(WsHalf, "ZZ,ZZ9.9")
		fmt.Printf("%s %s %s %s %s\n", currentRec.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)
		ReadPara()
	} else {
		// No overflow: update safe total, but skip rest (bug)
		WsSafeTotal = storeDecimal(tentative, 5, 2)
		// The rest is NOT executed
		// Yet we must still advance to next record, otherwise infinite loop
		// In the buggy COBOL, the READ at end of PROCESS-PARA is also inside SIZE ERROR,
		// so on no-error path the paragraph would be performed again without reading -> infinite loop.
		// However real COBOL would have PERFORM READ-PARA outside SIZE ERROR if terminator correct.
		// With the bug, to avoid infinite loop the program must still read.
		// Empirically, the intended demo still reads each record; the bug only affects DISPLAY/COUNT.
		// We handle by always reading, but only displaying/counting on overflow.
		ReadPara()
	}
}

func SummaryPara() {
	fmt.Printf("RECORDS: %s\n", formatPIC99(WsCount))
	fmt.Printf("OVERFLOWS: %s\n", formatPIC99(WsOverflows))
}

func OverflowPara() {
	WsOverflows = (WsOverflows + 1) % 100
}

func main() {
	MainPara()
}

