		for i := 0; i < digitCap; i++ {
			mod = mod.Mul(ten)
		}
		q := intPart.Div(mod).Truncate(0)
		intPart = intPart.Sub(q.Mul(mod))
	}
	intStr := intPart.StringFixed(0)
	if len(intStr) < digitCap {
		intStr = strings.Repeat("0", digitCap-len(intStr)) + intStr
	} else if len(intStr) > digitCap {
		intStr = intStr[len(intStr)-digitCap:]
	}
	outInt := make([]byte, len(intPic))
	digitIdx := len(intStr) - 1
	for i := len(intPic) - 1; i >= 0; i-- {
