	if amtReader == nil {
		WsEofFlag = "Y"
		return
	}
	line, err := amtReader.ReadString('\n')
	if err != nil {
		if len(line) == 0 {
			WsEofFlag = "Y"
			return
		}
	}
	line = strings.TrimRight(line, "\r\n")
	if len(line) < 11 {
		line = line + strings.Repeat(" ", 11-len(line))
	}
	if len(line) > 11 {
		line = line[:11]
	}
	arAcct := line[0:4]
	arAmtRaw := line[4:11]
	digits := ""
	for _, ch := range arAmtRaw {
		if ch >= '0' && ch <= '9' {
